.target sm_89
.address_size 64
.extern .shared .align 16 .b8 dyn_smem[];
.visible .entry depthwise_kx1_f32(
    .param .u64 in_ptr,
    .param .u64 wt_ptr,
    .param .u64 bias_ptr,
    .param .u64 out_ptr,
    .param .u32 C,
    .param .u32 H,
    .param .u32 W,
    .param .u32 Ho,
    .param .u32 Wo,
    .param .u32 K,
    .param .u32 stride,
    .param .u32 pad,
    .param .u32 dil,
    .param .u32 has_bias
)
{
    .reg .u32 %r0, %r1, %r2, %r3, %r4, %r5, %r6, %r7, %r8, %r9;
    .reg .u32 %r10, %r11, %r12, %r13, %r14, %r15, %r16, %r17, %r18, %r19;
    .reg .u32 %r20, %r21, %r22, %r23, %r24, %r25, %r26, %r27, %r28, %r29;
    .reg .u32 %r30, %r31;
    .reg .s32 %s0, %s1, %s2, %s3, %s4, %s5, %s6, %s7, %s8, %s9;
    .reg .u64 %rd0, %rd1, %rd2, %rd3, %rd4, %rd5, %rd6, %rd7, %rd8, %rd9;
    .reg .u64 %rd10, %rd11, %rd12, %rd13, %rd14, %rd15;
    .reg .f32 %f0, %f1, %f2, %f3, %f4, %f5, %f6, %f7, %f8, %f9, %f10, %f11;
    .reg .pred %p0, %p1, %p2, %p3, %p4, %p5;
    ld.param.u64 %rd0, [in_ptr];
    ld.param.u64 %rd1, [wt_ptr];
    ld.param.u64 %rd2, [bias_ptr];
    ld.param.u64 %rd3, [out_ptr];
    ld.param.u32 %r10, [C];
    ld.param.u32 %r11, [H];
    ld.param.u32 %r12, [W];
    ld.param.u32 %r13, [Ho];
    ld.param.u32 %r14, [Wo];
    ld.param.u32 %r15, [K];
    ld.param.u32 %r16, [stride];
    ld.param.u32 %r17, [pad];
    ld.param.u32 %r18, [dil];
    ld.param.u32 %r19, [has_bias];
    mov.u32 %r0, %tid.x;                 // tx
    mov.u32 %r1, %tid.y;                 // ty
    mov.u32 %r2, %ntid.x;                // 32
    mov.u32 %r3, %ntid.y;                // 8
    shl.b32 %r23, %r3, 2;                // output tile height = ntid.y * 4
    shl.b32 %r4, %r2, 1;                 // tile width = ntid.x * 2 = 64 (2 cols/thread)
    mov.u32 %r9, %ctaid.x;
    mul.lo.u32 %r5, %r9, %r4;            // ow0 (CTA column base)
    shl.b32 %r27, %r0, 1;                // 2*tx
    add.u32 %r6, %r5, %r27;              // ow (column 0 of this thread)
    mov.u32 %r9, %ctaid.y;
    mul.lo.u32 %r7, %r9, %r23;           // oh0
    add.u32 %r8, %r7, %r1;               // oh (q=0)
    mov.u32 %r20, %ctaid.z;              // nc
    rem.u32 %r21, %r20, %r10;            // c
    cvt.s32.u32 %s0, %r7;
    cvt.s32.u32 %s1, %r16;
    cvt.s32.u32 %s2, %r17;
    mul.lo.s32 %s3, %s0, %s1;
    sub.s32 %s3, %s3, %s2;               // base_h = oh0*stride - pad
    cvt.s32.u32 %s4, %r5;
    mul.lo.s32 %s5, %s4, %s1;
    sub.s32 %s5, %s5, %s2;               // iw0 = ow0*stride - pad
    cvt.s32.u32 %s6, %r12;               // W
    cvt.s32.u32 %s9, %r11;               // H
    sub.u32 %r22, %r23, 1;
    mul.lo.u32 %r22, %r22, %r16;
    sub.u32 %r9, %r15, 1;
    mul.lo.u32 %r9, %r9, %r18;
    add.u32 %r22, %r22, %r9;
    add.u32 %r22, %r22, 1;               // ROWS = (TILE_OUT_H-1)*stride + (K-1)*dil + 1
    mov.u32 %r24, dyn_smem;              // shared tile base (ROWS x 64 floats)
    cvt.u64.u32 %rd4, %r20;
    cvt.u64.u32 %rd5, %r11;
    mul.lo.u64 %rd8, %rd4, %rd5;         // nc*H
    cvt.u64.u32 %rd5, %r12;
    mul.lo.u64 %rd8, %rd8, %rd5;         // nc*H*W
    mul.lo.u32 %r26, %r22, %r4;          // ROWS * 64 elements
    mul.lo.u32 %r29, %r2, %r3;           // threads per CTA (256)
    mul.lo.u32 %r25, %r1, %r2;
    add.u32 %r25, %r25, %r0;             // linear tid = staging index
$stage_loop:
    setp.lt.u32 %p0, %r25, %r26;
    @!%p0 bra $stage_done;
    shr.u32 %r28, %r25, 6;               // r = idx / 64
    and.b32 %r30, %r25, 63;              // col = idx % 64
    cvt.s32.u32 %s7, %r28;
    add.s32 %s8, %s3, %s7;               // gh = base_h + r
    cvt.s32.u32 %s0, %r30;
    add.s32 %s1, %s5, %s0;               // iw = iw0 + col
    setp.lt.s32 %p1, %s8, 0;
    setp.ge.s32 %p2, %s8, %s9;
    or.pred %p3, %p1, %p2;
    setp.lt.s32 %p1, %s1, 0;
    setp.ge.s32 %p2, %s1, %s6;
    or.pred %p4, %p1, %p2;
    or.pred %p4, %p4, %p3;
    cvt.s64.s32 %rd10, %s8;
    cvt.u64.u32 %rd11, %r12;
    mul.lo.s64 %rd10, %rd10, %rd11;      // gh*W
    cvt.s64.s32 %rd12, %s1;
    add.s64 %rd10, %rd10, %rd12;         // + iw
    add.s64 %rd10, %rd10, %rd8;          // + nc*H*W
    shl.b64 %rd10, %rd10, 2;
    add.s64 %rd10, %rd0, %rd10;          // in element byte address
    @%p4 mov.u64 %rd10, %rd0;            // clamp OOB address (source is ignored)
    shl.b32 %r31, %r25, 2;
    add.u32 %r31, %r24, %r31;
    cp.async.ca.shared.global [%r31], [%rd10], 4, %p4;  // async 4B stage; ignore-src zero-fills halo
    add.u32 %r25, %r25, %r29;
    bra $stage_loop;
$stage_done:
    cp.async.commit_group;
    cp.async.wait_group 0;
    bar.sync 0;
    cvt.u64.u32 %rd12, %r21;
    shl.b64 %rd13, %rd12, 2;
    add.s64 %rd14, %rd2, %rd13;
    mov.f32 %f11, 0f00000000;
    setp.ne.u32 %p5, %r19, 0;
    @%p5 ld.global.f32 %f11, [%rd14];    // bias[c] if present
    mov.f32 %f0, %f11;                   // acc q0 col0
    mov.f32 %f1, %f11;                   // acc q0 col1
    mov.f32 %f2, %f11;                   // acc q1 col0
    mov.f32 %f3, %f11;                   // acc q1 col1
    mov.f32 %f4, %f11;                   // acc q2 col0
    mov.f32 %f5, %f11;                   // acc q2 col1
    mov.f32 %f6, %f11;                   // acc q3 col0
    mov.f32 %f7, %f11;                   // acc q3 col1
    cvt.u64.u32 %rd15, %r15;
    mul.lo.u64 %rd15, %rd12, %rd15;
    shl.b64 %rd15, %rd15, 2;
    add.s64 %rd15, %rd1, %rd15;          // wt + c*K (byte address)
    mul.lo.u32 %r26, %r3, %r16;          // q row step = ntid.y*stride
    shl.b32 %r5, %r26, 6;                // *64 floats
    shl.b32 %r5, %r5, 2;                 // smem byte step between q taps
    mul.lo.u32 %r30, %r1, %r16;          // r = ty*stride + k*dil
    mov.u32 %r29, 0;                     // k
$kloop:
    setp.lt.u32 %p0, %r29, %r15;
    @!%p0 bra $store;
    cvt.u64.u32 %rd10, %r29;
    shl.b64 %rd10, %rd10, 2;
    add.s64 %rd10, %rd15, %rd10;
    ld.global.f32 %f8, [%rd10];          // w_k (reused for 8 outputs)
    shl.b32 %r31, %r30, 6;               // r*64
    add.u32 %r31, %r31, %r27;            // + 2*tx
    shl.b32 %r31, %r31, 2;
    add.u32 %r31, %r24, %r31;            // q0 shared addr (8B aligned)
    ld.shared.v2.f32 {%f9, %f10}, [%r31];
    fma.rn.f32 %f0, %f8, %f9, %f0;
    fma.rn.f32 %f1, %f8, %f10, %f1;
    add.u32 %r25, %r31, %r5;
    ld.shared.v2.f32 {%f9, %f10}, [%r25];
    fma.rn.f32 %f2, %f8, %f9, %f2;
    fma.rn.f32 %f3, %f8, %f10, %f3;
    add.u32 %r25, %r25, %r5;
    ld.shared.v2.f32 {%f9, %f10}, [%r25];
    fma.rn.f32 %f4, %f8, %f9, %f4;
    fma.rn.f32 %f5, %f8, %f10, %f5;
    add.u32 %r25, %r25, %r5;
    ld.shared.v2.f32 {%f9, %f10}, [%r25];
    fma.rn.f32 %f6, %f8, %f9, %f6;
    fma.rn.f32 %f7, %f8, %f10, %f7;
