$store:
    setp.ge.u32 %p0, %r6, %r14;
    @%p0 bra $done;
    add.u32 %r28, %r6, 1;
    setp.lt.u32 %p2, %r28, %r14;         // col1 valid
    cvt.u64.u32 %rd4, %r20;
    cvt.u64.u32 %rd5, %r13;
    mul.lo.u64 %rd6, %rd4, %rd5;         // nc*Ho
    cvt.u64.u32 %rd7, %r8;
    add.u64 %rd6, %rd6, %rd7;            // + oh
    cvt.u64.u32 %rd9, %r14;
    mul.lo.u64 %rd6, %rd6, %rd9;         // *Wo
    cvt.u64.u32 %rd11, %r6;
    add.u64 %rd6, %rd6, %rd11;           // + ow
    shl.b64 %rd6, %rd6, 2;
    add.s64 %rd6, %rd3, %rd6;            // out q0 col0 byte address (8B aligned, ow even)
    cvt.u64.u32 %rd10, %r3;
    mul.lo.u64 %rd10, %rd10, %rd9;
    shl.b64 %rd10, %rd10, 2;             // output byte step between q rows
    setp.lt.u32 %p1, %r8, %r13;
    and.pred %p3, %p1, %p2;              // row valid && both cols valid
    not.pred %p4, %p2;
    and.pred %p4, %p4, %p1;              // row valid && col1 invalid
