    @%p4 st.global.f32 [%rd6], %f0;
    add.s64 %rd6, %rd6, %rd10;
    add.u32 %r8, %r8, %r3;
    setp.lt.u32 %p1, %r8, %r13;
    and.pred %p3, %p1, %p2;
    not.pred %p4, %p2;
    and.pred %p4, %p4, %p1;
    @%p3 st.global.v2.f32 [%rd6], {%f2, %f3};
    @%p4 st.global.f32 [%rd6], %f2;
    add.s64 %rd6, %rd6, %rd10;
    add.u32 %r8, %r8, %r3;
    setp.lt.u32 %p1, %r8, %r13;
    and.pred %p3, %p1, %p2;
    not.pred %p4, %p2;
    and.pred %p4, %p4, %p1;
    @%p3 st.global.v2.f32 [%rd6], {%f4, %f5};
    @%p4 st.global.f32 [%rd6], %f4;
    add.s64 %rd6, %rd6, %rd10;
    add.u32 %r8, %r8, %r3;
    setp.lt.u32 %p1, %r8, %r13;
    and.pred %p3, %p1, %p2;
    not.pred %p4, %p2;
    and.pred %p4, %p4, %p1;
    @%p3 st.global.v2.f32 [%rd6], {%f6, %f7};
    @%p4 st.global.f32 [%rd6], %f6;
